import{z as B,x as d,o as E,c as p,q as l,j as i,D as e,d as r,s as o,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"索引组织表","description":"","frontmatter":{"title":"索引组织表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/index-organized-table.md","filePath":"cs/index-organized-table.md","lastUpdated":1791063341000}'),A={name:"cs/index-organized-table.md"};function c(m,a,D,T,h,u){const t=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=l('<h1 id="索引组织表" tabindex="-1">索引组织表 <a class="header-anchor" href="#索引组织表" aria-label="Permalink to &quot;索引组织表&quot;">​</a></h1><div class="epigraph"><p>没有独立堆：主键 B+ 的叶就是行。二级索引必须带回主键，范围主键是第一公民，随机主键是页分裂税。</p><footer>—— 据 Ramakrishnan and Gehrke index-organized；Oracle IOT；InnoDB 聚簇抽象</footer></div><p><a href="/cs/clustered-secondary-lookup">上一课</a>把回表说清。本课把聚簇一侧说绝：索引组织表（IOT）= 主键索引即表。引擎对照序列封口；事务进阶从时间戳排序再开。缺口是抽象合同，不只 InnoDB 商标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>堆表：插入有堆页选择（追加、FSM）。IOT：插入位置由主键唯一决定，叶满则分裂，与 B+ 分裂课同一算法，只是载荷是整行。溢出：行太大则叶存关键列+溢出指针，上一课变长仍适用。缺口是<strong>何时选 IOT</strong>：主键范围、点查 pk 为主、表不太宽；否则叶扇出差、二级回表键很长。</p><p>无主键：InnoDB 仍隐式聚簇行号；那是实现补丁，设计上应显式主键。Postgres 无 IOT 作为默认，堆是第一公民。</p><p><span class="marginnote">Oracle Index-Organized Tables 是教科书名字。二级索引存主键值，主键长则二级肥——复合主键要短。本课不推销某厂。</span></p><p><span class="marginnote">数字实例：二级索引的每条记录都带一份主键副本。主键从 8 字节的 bigint 换成 36 字符的 UUID，1 亿行的单个二级索引就要多背约 28 亿字节，接近 2.6 GB——这就是「复合主键要短」的具体分量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：短、稳定、与范围查询对齐的主键。二级：覆盖常用投影，减少回主键。分区可叠在 IOT 上（按主键前缀）。迁移堆→IOT 是整表重写。</p><p>并发：叶热点（单调主键插入）把 latch crabbing 打在同一右热叶上——可改哈希主键或打散，与 UUID 课的缓冲污染同一权衡。</p>',11)),(E(),i(s,null,{default:e(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PK%5B%22%E4%B8%BB%E9%94%AE%E9%94%AE%22%5D%20--%3E%20LEAF%5B%22%E5%8F%B6%E4%B8%8A%E6%95%B4%E8%A1%8C%22%5D%0A%20%20SEC%5B%22%E4%BA%8C%E7%BA%A7%22%5D%20--%3E%20PKV%5B%22%E5%AD%98%E4%B8%BB%E9%94%AE%E5%80%BC%22%5D%0A%20%20PKV%20--%3E%20LEAF%0A%20%20WIDE%5B%22%E8%BF%87%E5%AE%BD%E8%A1%8C%22%5D%20--%3E%20OV%5B%22%E6%BA%A2%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"扫描：主键序扫描即表扫描，zone map/BRIN 类结构在 IOT 上变成沿叶的区统计。vacuum：InnoDB purge undo；不是堆 vacuum，但叶页仍要合并。TDE 盖叶页与溢出页。",-1)),a[5]||(a[5]=n("p",null,"单调主键的「页分裂税」是怎么收的：",-1)),(E(),i(s,null,{default:e(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%96%B0%E8%A1%8C%E4%B8%BB%E9%94%AE%E6%80%BB%E6%98%AF%E6%9C%80%E5%A4%A7%EF%BC%88%E8%87%AA%E5%A2%9E%20id%EF%BC%89%22%5D%20--%3E%20R%5B%22%E6%8F%92%E5%85%A5%E4%BD%8D%E7%BD%AE%E6%B0%B8%E8%BF%9C%E5%9C%A8%E6%9C%80%E5%8F%B3%E5%8F%B6%22%5D%0A%20%20R%20--%3E%20HOT%5B%22%E5%B9%B6%E5%8F%91%E5%86%99%E5%85%A8%E9%83%A8%E6%8C%A4%E5%90%91%E5%90%8C%E4%B8%80%E7%83%AD%E5%8F%B6%22%5D%0A%20%20HOT%20--%3E%20L%5B%22latch%20%E4%BA%89%E7%94%A8%20%2B%20%E5%8F%B6%E5%8F%8D%E5%A4%8D%E5%88%86%E8%A3%82%22%5D%0A%20%20L%20--%3E%20FIX%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9A%E5%93%88%E5%B8%8C%E4%B8%BB%E9%94%AE%E6%88%96%E6%89%93%E6%95%A3%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">术语翻译：「latch crabbing」（螃蟹爬行）指并发改 B+ 树时锁从父页一格格移交到子页，像螃蟹横着挪步。单调插入让所有螃蟹都挤最右边那一页，锁竞争全集中在一点——这就是叶热点的来源。</span></p><p>优化器：表扫描代价按叶链页数，不是堆占用（含空洞）的同一公式——膨胀定义不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲时间戳排序并发。也不把 IOT 当列存。存储进阶结束：从缓冲策略、索引族、列格式到两家行引擎。</p><p><span class="marginnote">常见误区：初学者容易以为 IOT 是「表加了个索引」，实际上它没有独立的堆——主键 B+ 树的叶子本身就是行存放的地方。选主键因此不是命名习惯问题，而是直接决定数据在磁盘上的物理顺序。</span></p><p>后课默认：IOT 让 pk 范围顺序化，二级回主键。时间戳排序：不用 2PL，按时间戳接受或拒绝读写。</p><p>主键即布局。选错主键就是选错物理序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IOT 叶内存行；二级回主键；主键应短而稳定。</li><li>单调插入热叶是并发与缓冲问题。</li><li>下一单元时间戳排序：并发控制续的第一课。</li><li>出处：Ramakrishnan and Gehrke；Oracle IOT；InnoDB 聚簇。</li></ul>',9))])}const _=B(A,[["render",c]]);export{b as __pageData,_ as default};
